WITH metrics AS (SELECT *, MAX(balance) OVER w_hist AS account_type_max_balance, FIRST_VALUE(status) IGNORE NULLS OVER (PARTITION BY status ORDER BY opened_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_status FROM accounts WINDOW w_hist AS (PARTITION BY account_type)) SELECT customer_id, account_type, COUNT(*) FILTER (WHERE status = 'CLOSED') AS closed_rows, ROUND(SUM(account_type_max_balance) / NULLIF(COUNT(CASE WHEN status = 'CLOSED' THEN 1 END), 0), 2) AS account_type_max_balance_per_closed, SUM(CASE WHEN account_type = 'SAVINGS' THEN account_type_max_balance ELSE 0 END) AS savings_account_type_max_balance, COUNT(*) AS row_count, APPROX_PERCENTILE(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, COUNT_IF(account_type = 'CHECKING') AS checking_events FROM metrics GROUP BY CUBE (customer_id, account_type) HAVING closed_rows > 1;
